// resolve.mjs — PyYAML safe_load-compatible plain-scalar resolver (pure ESM, no deps,
// no RegExp, no JSON; all parsing is done char-by-char).
//
// INTERFACE (consumed by the dumper agent):
//
//   resolveScalar(plainStr) -> JS value
//     Takes the raw text of a PLAIN (unquoted) scalar, exactly as it appears in the
//     source document, and returns the value PyYAML's safe_load would resolve it to:
//       'null'/'Null'/'NULL'/'~'/''  -> null
//       yes/no/true/false/on/off in PyYAML's 18 case variants -> true/false
//       ints (incl. +/- sign, 0x hex, 0b binary, 0-prefixed octal, underscores,
//             sexagesimal like '1:30' -> 90)  -> Number
//       floats (dot required, or .inf/-.inf/.nan; scientific notation only WITH an
//             exponent sign, e.g. '1.5E+3'; '1e3' and '1.5e3' stay STRINGS) -> Number
//       '.inf'/'+.inf' -> Infinity, '-.inf' -> -Infinity, '.nan' -> NaN
//       everything else (timestamps like '2020-01-01', '0o17', '1e3', ...) -> the
//       original string, unchanged.
//
//   isPlainSafe(str, context) -> boolean
//     Whether the dumper may emit the *string* `str` as a plain (unquoted) scalar
//     without changing its meaning on re-load. `context` is one of:
//       'block' (default) — value/key position in block style
//       'flow'            — inside [ ... ] / { ... }
//       'key'             — block simple-key position (like 'block', but also rejects
//                           empty/multiline; note: keys longer than 128 chars force the
//                           explicit '? ' form, which is the dumper's concern, not this
//                           predicate's)
//       'flow-key'        — simple-key position inside flow context
//     Mirrors PyYAML emitter.analyze_scalar + choose_scalar_style for a str scalar:
//     rejects strings that resolve to a non-str tag (null/bool/int/float/timestamp/
//     '='/'<<'), empty strings, leading/trailing whitespace, any line breaks, any char
//     outside 0x20–0x7E (yaml.dump default allow_unicode=False -> non-ASCII and control
//     chars are double-quoted), leading indicator chars ('#,[]{}&*!|>\'"%@`', plus
//     '-' '?' ':' when followed by whitespace/end), '---'/'...' prefixes, inner ': '
//     and ' #' sequences (block) and ',?[]{}:' chars (flow).
//
// Calibration was done against the reference executable (PyYAML with default dump
// settings: block style, allow_unicode=False).

const BOOL_MAP = new Map([
  ['yes', true], ['Yes', true], ['YES', true],
  ['no', false], ['No', false], ['NO', false],
  ['true', true], ['True', true], ['TRUE', true],
  ['false', false], ['False', false], ['FALSE', false],
  ['on', true], ['On', true], ['ON', true],
  ['off', false], ['Off', false], ['OFF', false],
]);

function isDigit(ch) {
  return ch >= '0' && ch <= '9';
}

function isHexDigit(ch) {
  return (ch >= '0' && ch <= '9') || (ch >= 'a' && ch <= 'f') || (ch >= 'A' && ch <= 'F');
}

// All chars are digits or underscores, at least one char. Returns digit-only string.
function stripDigitsUnderscores(s, i0, i1) {
  let out = '';
  for (let i = i0; i < i1; i++) {
    const ch = s[i];
    if (ch === '_') continue;
    if (!isDigit(ch)) return null;
    out += ch;
  }
  if (out.length === 0 && i1 === i0) return null; // empty range
  return out;
}

// ---------------------------------------------------------------------------
// Integer parsing, mirroring PyYAML's int resolver regex:
//   ^(?: [-+]?0b[0-1_]+
//      | [-+]?0[0-7_]+
//      | [-+]?(?:0|[1-9][0-9_]*)
//      | [-+]?0x[0-9a-fA-F_]+
//      | [-+]?[1-9][0-9_]*(?::[0-5]?[0-9])+ )$
// Returns a Number, or null if `s` is not an int resolution.
// ---------------------------------------------------------------------------
function parseYamlInt(s) {
  let i = 0;
  let neg = false;
  if (s[0] === '+' || s[0] === '-') {
    neg = s[0] === '-';
    i = 1;
  }
  const rest = s.slice(i);
  if (rest.length === 0) return null;

  const finish = (v) => {
    if (v === 0) return 0; // normalize -0
    return neg ? -v : v;
  };

  // 0b binary
  if (rest[0] === '0' && rest[1] === 'b') {
    if (rest.length < 3) return null;
    let v = 0;
    for (let k = 2; k < rest.length; k++) {
      const ch = rest[k];
      if (ch === '_') continue;
      if (ch !== '0' && ch !== '1') return null;
      v = v * 2 + (ch === '1' ? 1 : 0);
    }
    return finish(v);
  }

  // 0x hex (lowercase 'x' only; '0X1A' stays a string)
  if (rest[0] === '0' && rest[1] === 'x') {
    if (rest.length < 3) return null;
    let digits = '';
    for (let k = 2; k < rest.length; k++) {
      const ch = rest[k];
      if (ch === '_') continue;
      if (!isHexDigit(ch)) return null;
      digits += ch;
    }
    // Number('0x' + '') would be NaN; require at least one real digit via parseInt.
    const v = parseInt(digits, 16);
    if (Number.isNaN(v)) return null;
    return finish(v);
  }

  // 0-prefixed octal: 0[0-7_]+ (e.g. '017' -> 15, '0_7' -> 7). '08' is NOT an int.
  if (rest[0] === '0' && rest.length > 1 && rest[1] !== ':') {
    let allOctal = true;
    let v = 0;
    for (let k = 1; k < rest.length; k++) {
      const ch = rest[k];
      if (ch === '_') continue;
      if (ch < '0' || ch > '7') { allOctal = false; break; }
      v = v * 8 + (ch.charCodeAt(0) - 48);
    }
    if (allOctal) return finish(v);
    return null; // leading zero but not octal -> not an int ('08', '0.5' handled elsewhere)
  }

  // plain zero
  if (rest === '0') return 0;

  // decimal [1-9][0-9_]*, possibly sexagesimal [1-9][0-9_]*(:[0-5]?[0-9])+
  if (rest[0] >= '1' && rest[0] <= '9') {
    // find first group
    let k = 1;
    while (k < rest.length && (isDigit(rest[k]) || rest[k] === '_')) k++;
    const firstDigits = stripDigitsUnderscores(rest, 0, k);
    if (firstDigits === null) return null;
    if (k === rest.length) {
      return finish(parseInt(firstDigits, 10));
    }
    if (rest[k] === ':') {
      // sexagesimal: one or more :[0-5]?[0-9] groups, must reach end of string
      let v = parseInt(firstDigits, 10);
      while (k < rest.length && rest[k] === ':') {
        k++;
        let g = 0;
        let cnt = 0;
        while (k < rest.length && isDigit(rest[k]) && cnt < 2) {
          g = g * 10 + (rest[k].charCodeAt(0) - 48);
          k++;
          cnt++;
        }
        if (cnt === 0) return null;
        if (cnt === 2 && g > 59) return null; // [0-5]?[0-9]
        if (cnt === 2 && rest[k - 2] > '5') return null;
        v = v * 60 + g;
      }
      if (k !== rest.length) return null; // e.g. '1:30.5' is a float, handled below
      return finish(v);
    }
    return null;
  }

  return null;
}

// ---------------------------------------------------------------------------
// Float parsing, mirroring PyYAML's float resolver regex:
//   ^(?: [-+]?(?:[0-9][0-9_]*)\.[0-9_]*(?:[eE][-+][0-9]+)?
//      | \.[0-9][0-9_]*(?:[eE][-+][0-9]+)?
//      | [-+]?[0-9][0-9_]*(?::[0-5]?[0-9])+\.[0-9_]*
//      | [-+]?\.(?:inf|Inf|INF)
//      | \.(?:nan|NaN|NAN) )$
// Note: the exponent REQUIRES an explicit sign ('1.5E+3' floats, '1.5e3' is a string).
// Returns a Number, or null if `s` is not a float resolution.
// ---------------------------------------------------------------------------
function parseYamlFloat(s) {
  let i = 0;
  let neg = false;
  let hasSign = false;
  if (s[0] === '+' || s[0] === '-') {
    hasSign = true;
    neg = s[0] === '-';
    i = 1;
  }
  const rest = s.slice(i);
  if (rest.length === 0) return null;

  // .inf / .nan specials
  if (rest === '.inf' || rest === '.Inf' || rest === '.INF') {
    return neg ? -Infinity : Infinity;
  }
  if (!hasSign && (rest === '.nan' || rest === '.NaN' || rest === '.NAN')) {
    return NaN; // sign is NOT allowed for nan ('-.nan' stays a string)
  }

  // helper: parse optional exponent starting at index p in `rest`.
  // Requires [eE][-+][0-9]+ if present; returns end index or -1 on mismatch.
  const exponentEnd = (p) => {
    if (p >= rest.length) return p;
    if (rest[p] !== 'e' && rest[p] !== 'E') return p;
    p++;
    if (p >= rest.length || (rest[p] !== '+' && rest[p] !== '-')) return -1;
    p++;
    const start = p;
    while (p < rest.length && isDigit(rest[p])) p++;
    if (p === start) return -1;
    return p;
  };

  // sexagesimal float: [0-9][0-9_]*(:[0-5]?[0-9])+\.[0-9_]*
  if (isDigit(rest[0])) {
    let k = 0;
    while (k < rest.length && (isDigit(rest[k]) || rest[k] === '_')) k++;
    if (k < rest.length && rest[k] === ':') {
      const firstDigits = stripDigitsUnderscores(rest, 0, k);
      let v = parseInt(firstDigits, 10);
      while (k < rest.length && rest[k] === ':') {
        k++;
        let g = 0;
        let cnt = 0;
        while (k < rest.length && isDigit(rest[k]) && cnt < 2) {
          g = g * 10 + (rest[k].charCodeAt(0) - 48);
          k++;
          cnt++;
        }
        if (cnt === 0) return null;
        if (cnt === 2 && rest[k - 2] > '5') return null;
        v = v * 60 + g;
      }
      if (k < rest.length && rest[k] === '.') {
        k++;
        const fracStart = k;
        while (k < rest.length && (isDigit(rest[k]) || rest[k] === '_')) k++;
        if (k !== rest.length) return null;
        const frac = stripDigitsUnderscores(rest, fracStart, k);
        let fv = v;
        if (frac !== null && frac.length > 0) {
          fv = v + parseInt(frac, 10) / Math.pow(10, frac.length);
        }
        if (fv === 0) return 0;
        return neg ? -fv : fv;
      }
      return null; // pure sexagesimal int already handled by parseYamlInt
    }
  }

  // decimal float: [0-9][0-9_]*\.[0-9_]*(exp)?  or  \.[0-9][0-9_]*(exp)?
  let k = 0;
  let intDigits = '';
  if (isDigit(rest[0])) {
    while (k < rest.length && (isDigit(rest[k]) || rest[k] === '_')) k++;
    intDigits = stripDigitsUnderscores(rest, 0, k);
  } else if (rest[0] !== '.') {
    return null;
  }
  if (k >= rest.length || rest[k] !== '.') return null;
  k++;
  const fracStart = k;
  while (k < rest.length && (isDigit(rest[k]) || rest[k] === '_')) k++;
  const fracDigits = stripDigitsUnderscores(rest, fracStart, k);
  if (fracDigits === null) return null;
  if (intDigits.length === 0 && fracDigits.length === 0) return null; // bare '.'
  if (intDigits.length === 0 && fracStart === k) return null; // '.' with nothing after
  // case '.[0-9][0-9_]*' requires at least one frac digit when no int part
  const eEnd = exponentEnd(k);
  if (eEnd === -1 || eEnd !== rest.length) return null; // e.g. '1.5e3' (no exp sign) -> string
  let numStr = (intDigits.length > 0 ? intDigits : '0') + '.' + (fracDigits.length > 0 ? fracDigits : '0');
  if (eEnd > k) numStr += rest.slice(k, eEnd); // includes 'E+3' etc.
  const v = Number(numStr);
  if (Number.isNaN(v)) return null;
  if (v === 0) return 0;
  return neg ? -v : v;
}

// ---------------------------------------------------------------------------
// Timestamp detection, mirroring PyYAML's timestamp resolver regex:
//   ^(?: [0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]
//      | [0-9][0-9][0-9][0-9]-[0-9][0-9]?-[0-9][0-9]?(?:[Tt]|[ \t]+)
//        [0-9][0-9]?:[0-5][0-9]:[0-5][0-9](?:\.[0-9]*)?
//        (?:[ \t]*(?:Z|[-+][0-9][0-9]?(?::[0-5][0-9])?))? )$
// Only used by isPlainSafe (a string that resolves to a timestamp must be quoted);
// resolveScalar itself keeps timestamps as plain strings per the shared spec.
// ---------------------------------------------------------------------------
function isTimestampLike(s) {
  const n = s.length;
  // form 1: YYYY-MM-DD (all two-digit), exactly
  if (n === 10) {
    let ok = true;
    for (let p = 0; p < 10; p++) {
      if (p === 4 || p === 7) {
        if (s[p] !== '-') { ok = false; break; }
      } else if (!isDigit(s[p])) { ok = false; break; }
    }
    if (ok) return true;
  }
  // form 2: full timestamp
  let p = 0;
  if (n < 4) return false;
  for (let q = 0; q < 4; q++) {
    if (!isDigit(s[q])) return false;
  }
  p = 4;
  if (s[p] !== '-') return false;
  p++;
  let cnt = 0;
  while (p < n && isDigit(s[p]) && cnt < 2) { p++; cnt++; }
  if (cnt === 0) return false;
  if (s[p] !== '-') return false;
  p++;
  cnt = 0;
  while (p < n && isDigit(s[p]) && cnt < 2) { p++; cnt++; }
  if (cnt === 0) return false;
  // separator: T/t or one-or-more space/tab
  if (p >= n) return false;
  if (s[p] === 'T' || s[p] === 't') {
    p++;
  } else if (s[p] === ' ' || s[p] === '\t') {
    while (p < n && (s[p] === ' ' || s[p] === '\t')) p++;
  } else {
    return false;
  }
  // hour: 1-2 digits
  cnt = 0;
  while (p < n && isDigit(s[p]) && cnt < 2) { p++; cnt++; }
  if (cnt === 0) return false;
  // :MM
  if (s[p] !== ':') return false;
  p++;
  if (p + 1 >= n || s[p] < '0' || s[p] > '5' || !isDigit(s[p + 1])) return false;
  p += 2;
  // :SS
  if (s[p] !== ':') return false;
  p++;
  if (p + 1 >= n || s[p] < '0' || s[p] > '5' || !isDigit(s[p + 1])) return false;
  p += 2;
  // optional fraction: .[0-9]*
  if (p < n && s[p] === '.') {
    p++;
    while (p < n && isDigit(s[p])) p++;
  }
  // optional timezone: [ \t]*( Z | [-+][0-9][0-9]?(?::[0-5][0-9])? )
  if (p < n && (s[p] === ' ' || s[p] === '\t')) {
    while (p < n && (s[p] === ' ' || s[p] === '\t')) p++;
  }
  if (p >= n) return true;
  if (s[p] === 'Z') {
    p++;
    return p === n;
  }
  if (s[p] === '+' || s[p] === '-') {
    p++;
    cnt = 0;
    while (p < n && isDigit(s[p]) && cnt < 2) { p++; cnt++; }
    if (cnt === 0) return false;
    if (p < n && s[p] === ':') {
      p++;
      if (p + 1 >= n || s[p] < '0' || s[p] > '5' || !isDigit(s[p + 1])) return false;
      p += 2;
    }
    return p === n;
  }
  return false;
}

/**
 * Resolve the raw text of a PLAIN (unquoted) YAML scalar exactly as
 * PyYAML's safe_load would. See the interface note at the top of this file.
 */
export function resolveScalar(plainStr) {
  const s = String(plainStr);
  // null
  if (s === '' || s === '~' || s === 'null' || s === 'Null' || s === 'NULL') {
    return null;
  }
  // bool
  if (BOOL_MAP.has(s)) {
    return BOOL_MAP.get(s);
  }
  // int / float (leading chars other than sign/digit/dot can't be numeric)
  const c0 = s[0];
  if (c0 === '+' || c0 === '-' || c0 === '.' || isDigit(c0)) {
    const asInt = parseYamlInt(s);
    if (asInt !== null) return asInt;
    const asFloat = parseYamlFloat(s);
    if (asFloat !== null) return asFloat;
  }
  // everything else (incl. timestamps, '0o17', '1e3', ...) stays a string
  return s;
}

const WS_CHARS = ' \t\r\n\x00\x85\u2028\u2029';

function isYamlWhitespace(ch) {
  return WS_CHARS.indexOf(ch) !== -1;
}

function isLineBreak(ch) {
  return ch === '\n' || ch === '\x85' || ch === '\u2028' || ch === '\u2029';
}

// Would PyYAML's resolver detect a non-str tag for this plain scalar?
function resolvesToNonStr(s) {
  if (typeof resolveScalar(s) !== 'string') return true; // null/bool/int/float
  if (s === '=') return true;  // tag:yaml.org,2002:value
  if (s === '<<') return true; // tag:yaml.org,2002:merge
  if (isTimestampLike(s)) return true; // tag:yaml.org,2002:timestamp
  return false;
}

/**
 * Whether the dumper may emit string `str` as a plain (unquoted) scalar in the
 * given context ('block' | 'flow' | 'key' | 'flow-key'; default 'block').
 * Mirrors PyYAML's emitter.analyze_scalar + choose_scalar_style for str scalars
 * with default dump settings (block style, allow_unicode=False).
 */
export function isPlainSafe(str, context = 'block') {
  const s = String(str);
  const inFlow = context === 'flow' || context === 'flow-key';
  const inKey = context === 'key' || context === 'flow-key';

  if (s.length === 0) return false;

  // Plain emission requires implicit round-trip: the scalar must resolve back
  // to a plain string, not null/bool/int/float/timestamp/value/merge.
  if (resolvesToNonStr(s)) return false;

  // '---' / '...' prefixes are document indicators.
  if (s.startsWith('---') || s.startsWith('...')) return false;

  const n = s.length;

  // leading/trailing space or line break
  if (s[0] === ' ' || isLineBreak(s[0])) return false;
  if (s[n - 1] === ' ' || isLineBreak(s[n - 1])) return false;

  // leading indicator characters (index 0)
  const c0 = s[0];
  if ('#,[]{}&*!|>\'"%@`'.indexOf(c0) !== -1) return false;
  const followedByWs0 = n === 1 || isYamlWhitespace(s[1]);
  if (c0 === '?' || c0 === ':') {
    if (inFlow || followedByWs0) return false;
  }
  if (c0 === '-' && followedByWs0) return false;

  // scan the rest
  for (let i = 0; i < n; i++) {
    const ch = s[i];
    // any line break forbids plain style (PyYAML uses single-quoted multiline)
    if (isLineBreak(ch)) return false;
    // with allow_unicode=False everything outside 0x20-0x7E is "special"
    // (control chars, tabs, non-ASCII) and forces double quotes
    const code = ch.charCodeAt(0);
    if (code < 0x20 || code > 0x7e) return false;
    if (i > 0) {
      const followedByWs = i + 1 >= n || isYamlWhitespace(s[i + 1]);
      const precededByWs = isYamlWhitespace(s[i - 1]);
      if (inFlow && (ch === ',' || ch === '?' || ch === '[' || ch === ']' ||
                     ch === '{' || ch === '}')) {
        return false;
      }
      if (ch === ':') {
        if (inFlow || followedByWs) return false;
      }
      if (ch === '#' && precededByWs) return false;
    }
  }

  // simple-key context additionally forbids empty (handled) and multiline (handled);
  // the 128-char simple-key length limit only forces the explicit '? ' key form,
  // which still allows a plain scalar, so it is NOT this predicate's concern.
  void inKey;

  return true;
}

import { resolveScalar, isPlainSafe } from '/output/yaml/resolve.mjs';

let fails = 0;
function eq(actual, expected, label) {
  let ok;
  if (typeof expected === 'number' && Number.isNaN(expected)) ok = Number.isNaN(actual);
  else ok = Object.is(actual, expected);
  if (!ok) { fails++; console.log(`FAIL ${label}: got ${JSON.stringify(actual)} want ${JSON.stringify(expected)}`); }
}

// resolveScalar — values verified against the executable
const cases = [
  ['null', null], ['Null', null], ['NULL', null], ['~', null], ['', null],
  ['yes', true], ['Yes', true], ['YES', true], ['no', false], ['No', false], ['NO', false],
  ['true', true], ['True', true], ['TRUE', true], ['false', false], ['False', false], ['FALSE', false],
  ['on', true], ['On', true], ['ON', true], ['off', false], ['Off', false], ['OFF', false],
  ['y', 'y'], ['n', 'n'],
  ['0o17', '0o17'], ['017', 15], ['0x1A', 26], ['0b101', 5], ['1_000', 1000],
  ['+42', 42], ['-42', -42], ['1e3', '1e3'], ['1.5e3', '1.5e3'], ['1.5E+3', 1500],
  ['.inf', Infinity], ['-.Inf', -Infinity], ['.NaN', NaN], ['-.nan', '-.nan'],
  ['1.', 1], ['.5', 0.5], ['+1.5', 1.5], ['01_0', 8], ['0x1_a', 26], ['12_', 12],
  ['00', 0], ['0', 0], ['-0', 0],
  ['08', '08'], ['0_7', 7], ['+0x1F', 31], ['1:30', 90], ['1:30.5', 90.5],
  ['1:5', 65], ['1:60', '1:60'], ['+1_000', 1000], ['1.5e-3', 0.0015], ['.5e+2', 50],
  ['1:2:3', 3723], ['1__2', 12], ['_1', '_1'], ['0o178', '0o178'], ['0x', '0x'],
  ['2020-01-01', '2020-01-01'], ['nulls', 'nulls'], ['truee', 'truee'],
  ['-1:30', -90], ['+1:30', 90], ['0X1A', '0X1A'], ['0B101', '0B101'], ['-0x10', -16],
  ['1_0.5', 10.5], ['1_0', 10], ['00.5', 0.5], ['-0.5', -0.5], ['10:20:30.5', 37230.5],
  ['9:99', '9:99'], ['1:60.5', '1:60.5'], ['12:34', 754], ['.infx', '.infx'],
  ['nan', 'nan'], ['inf', 'inf'], ['1.e3', '1.e3'], ['0.e1', '0.e1'], ['+.inf', Infinity],
];
for (const [inp, exp] of cases) eq(resolveScalar(inp), exp, `resolveScalar(${inp})`);
eq(Object.is(resolveScalar('-0'), -0), false, '-0 is +0');

// isPlainSafe — block context, from observed dump output
const plain = [
  ['1.0', false], ['abc', true], ['a b', true], ['a: b', false], ['-x', true],
  ['- x', false], [' a', false], ['a #b', false], ['', false], ['null', false],
  ['yes', false], ['1e3', true], ['0o17', true], ['2020-01-01', false],
  ['=', false], ['<<', false], ['---x', false], ['...x', false], ['x\ty', false],
  ['x,', true], ['x:', false], ['#x', false], ['%x', false], ['@x', false],
  ['`x', false], ['!x', false], ['?x', true], ['? x', false], ['x?', true],
  ['x*', true], ['&x', false], ['[x', false], ['x#', true], ['x&y', true],
